1	/**
2	 * Cookie-consent state, shared between the banner and the two floating widgets
3	 * it used to sit on top of.
4	 *
5	 * The banner (`components/marketing/CookieConsent.tsx`), the chat bubble
6	 * (`components/ChatWidget.tsx`) and the feedback button
7	 * (`components/FeedbackWidget.tsx`) all occupy the bottom of the viewport. On a
8	 * first visit the banner is the only one of the three the visitor must act on,
9	 * so it wins the stacking order — and the other two get out of its way until a
10	 * choice exists. That needs one definition of "has a choice been made", plus a
11	 * way for the widgets to hear about the choice the moment it is made rather than
12	 * on the next page load.
13	 *
14	 * Browser-only module: no imports, safe in any client component.
15	 */
16	
17	export const CONSENT_COOKIE = "nxeon_cookie_consent";
18	export const CONSENT_MAX_AGE = 60 * 60 * 24 * 365;
19	
20	/** Fired on `window` when a visitor accepts or declines, so widgets re-measure. */
21	export const CONSENT_EVENT = "nxeon:cookie-consent";
22	
23	/** True once the visitor has chosen. SSR-safe: assumes chosen, so nothing moves. */
24	export function hasCookieConsent(): boolean {
25	  if (typeof document === "undefined") return true;
26	  try {
27	    return document.cookie.split("; ").some((c) => c.startsWith(`${CONSENT_COOKIE}=`));
28	  } catch {
29	    // Cookies blocked entirely — treat as decided so we never pin a banner-shaped
30	    // hole in the corner of a page whose banner will never appear.
31	    return true;
32	  }
33	}
34	
35	export function setCookieConsent(value: "all" | "necessary") {
36	  document.cookie = `${CONSENT_COOKIE}=${value}; path=/; max-age=${CONSENT_MAX_AGE}; SameSite=Lax`;
37	}
