27	export type FulfilResult = {
28	  /** Where the browser should end up. The webhook ignores this. */
29	  redirect: string;
30	  /** True when THIS call performed the fulfilment work. */
31	  fulfilled: boolean;
32	  kind: "order" | "gameOrder" | "resize" | "diskExpand" | "topup" | "none";
