36	/**
37	 * Claim exclusive responsibility for fulfilling `sessionId`.
38	 * Returns false when another caller already holds the claim — the UNIQUE index,
39	 * not a read-then-write check, is what makes this safe under concurrency.
40	 */
41	async function claim(sessionId: string, kind: string): Promise<boolean> {
42	  try {
43	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionId, kind } });
44	    return true;
45	  } catch (e) {
46	    if ((e as { code?: string })?.code === "P2002") return false; // someone else has it
47	    throw e;
48	  }
49	}
