51	async function settle(sessionId: string, status: "DONE" | "FAILED", detail?: string) {
52	  await db.fulfilledSession
53	    .update({ where: { stripeSessionId: sessionId }, data: { status, detail: detail?.slice(0, 500) } })
54	    .catch(() => {});
55	}
56	
57	/**
58	 * Tell the customer their money is safe and someone knows. Called only on a path
59	 * where the card HAS cleared and fulfilment did not happen, so silence is the one
60	 * outcome that is never acceptable.
61	 */
62	async function notifyStalled(userId: string) {
63	  await db.notification
64	    .create({
65	      data: {
66	        userId,
67	        title: "Payment received — we couldn't finish setting up your server",
68	        body: "Your payment is safe and sitting in your wallet. Our team has been alerted; deploy again or contact support and we'll sort it out.",
69	        href: "/dashboard/billing",
70	      },
71	    })
72	    .catch(() => {});
73	}
