75	/**
76	 * Credit the wallet and fulfil whatever the session was for, exactly once.
77	 * Safe to call repeatedly and concurrently from the redirect and the webhook.
78	 *
79	 * THROWS when Stripe cannot be read. That is deliberate and it is the fix for the
80	 * defect found on 2026-07-27: this function used to ask three helpers for the
81	 * session, each of which swallowed every error into `null`, so a transient Stripe
82	 * failure was indistinguishable from "no purchase metadata" and fell through to
83	 * the top-up branch below reporting `fulfilled: true`. A real order then had its
84	 * card charged with no server, no FulfilledSession row and no notification — and
85	 * because the webhook returns 200 either way, Stripe never retried it. A throw
86	 * lands the browser on `?pending=1` (see app/api/stripe/confirm) and puts the
87	 * failure in the webhook's log, which is loud; declaring it a top-up was silent.
88	 */
89	export async function fulfilCheckoutSession(sessionId: string, base = ""): Promise<FulfilResult> {
90	  // ONE retrieve, one view of the session, shared by the credit and the routing.
91	  const session = await retrieveCheckoutSession(sessionId);
92	  const purpose = classifyCheckoutSession(session);
93	
94	  // Nothing was paid (an abandoned session id, or one replayed before capture).
95	  // Never claim fulfilment for money that has not arrived.
96	  if (purpose.kind === "unpaid") {
97	    return { redirect: `${base}/dashboard/billing`, fulfilled: false, kind: "none" };
98	  }
99	
100	  // Crediting is separately idempotent (UNIQUE stripeSessionId on the wallet
101	  // transaction). We deliberately IGNORE its return value now — it reports who
102	  // won the credit race, which is not the same question as "has this been
103	  // fulfilled", and conflating the two was the bug. A THROW, however, is not a
104	  // race: the money has not reached the wallet, so nothing below may spend it.
105	  await creditCheckoutSession(session);
106	
107	  // Purchase metadata is present but cannot be trusted. Retrying will never fix
108	  // it, so claim the session and record the failure exactly like a failed order:
109	  // reconcilable, and the customer is told. What it must NEVER become is a silent
110	  // wallet top-up, which is precisely what the old `null` fall-through produced.
111	  if (purpose.kind === "unreadable") {
112	    if (await claim(sessionId, "unreadable")) {
113	      await settle(sessionId, "FAILED", purpose.detail);
114	      if (purpose.userId) await notifyStalled(purpose.userId);
115	    }
116	    return {
117	      redirect: `${base}/dashboard/billing?paid=1`,
118	      fulfilled: false,
119	      kind: "none",
120	      error: purpose.detail,
121	    };
122	  }
123	
124	  const order = purpose.kind === "order" ? purpose : null;
125	  if (order) {
126	    if (!(await claim(sessionId, "order"))) {
127	      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "order" };
128	    }
129	    try {
130	      const user = await db.user.findUnique({ where: { id: order.userId } });
131	      if (!user) throw new Error("user not found for paid order");
132	      // Settle the price stamped on the session BEFORE the card was charged — never
133	      // a fresh quote taken now. The customer has already paid the card leg of that
134	      // exact total; re-pricing here and taking the difference out of the wallet is
135	      // the H2 incident (see OrderPrice in lib/order.ts). This is the same shape as
136	      // the resize and disk-expand branches below, which have always passed the
137	      // amount through metadata for this reason.
138	      // No request-scoped IP on the fulfil path (this can run in the webhook), so the
139	      // per-IP cap can't be enforced here — the per-account unique still holds, and
140	      // the first-month-free HOLD was already reserved (per-account AND per-IP) before
141	      // the card was charged, so the double-claim race is closed regardless. Fulfilment
142	      // CONFIRMS that hold via `promoReservationToken` rather than contending for a
143	      // fresh claim. `campaign` rides in via metadata so attribution survives the card
144	      // round-trip even in the webhook (no cookies).
145	      const serverId = await placeOrder(user, order.intent, order.sold, {
146	        ipHash: null,
147	        campaign: order.campaign,
148	        promoReservationToken: order.promoReservationToken,
149	        // Same discipline as the promo hold: the coupon was RESERVED (per-person + global
150	        // cap) before the card was charged, and placeOrder CONFIRMS that hold via this
151	        // token rather than contending for a fresh claim — no double-claim, no over-charge.
152	        couponReservationToken: order.couponReservationToken,
153	      });
154	      await settle(sessionId, "DONE", serverId);
155	      return { redirect: `${base}/dashboard/servers/${serverId}`, fulfilled: true, kind: "order" };
156	    } catch (e) {
157	      // Payment is captured and the funds are in the wallet — record the failure
158	      // so it is reconcilable rather than invisible, and tell the customer.
159	      const msg = String((e as Error)?.message ?? e);
160	      await settle(sessionId, "FAILED", msg);
161	      await notifyStalled(order.userId);
