/**
 * Every setting, with defaults merged under any stored overrides. Secret values
 * ARE included — callers that hand this to the client (the settings page) must
 * strip SECRET_KEYS themselves.
 */
export async function getAllSettings(): Promise<Record<string, string>> {
  const rows = await db.setting.findMany();
  const merged: Record<string, string> = { ...SETTINGS_DEFAULTS };
  for (const r of rows) merged[r.key] = r.value;
  return merged;
}

/**
 * The admin-configured default billing term, in MONTHS, guaranteed to be a term the
 * platform can actually sell.
 *
 * The guarantee is the point. `default_term` was previously the enum
 * "monthly"|"quarterly"|"annual" and the platform's real terms are 1/12/24/36 months
 * (`VPS_TERMS`) — "quarterly" mapped to nothing at all. Anything stored that
 * `VPS_TERMS` does not contain (a legacy row, or a hand-crafted POST that slipped past
 * the panel's enum check) falls back to the first term rather than pre-selecting a
 * commitment no charge path can price. A wizard that pre-selects an unsellable term
 * would fail at `vpsTerm()`'s own silent `?? VPS_TERMS[0]` fallback, charging monthly
 * while the review step displayed something else.
 */
export async function defaultTermMonths(): Promise<number> {
  const months = Number(await getSetting("default_term"));
  return VPS_TERMS.some((t) => t.months === months) ? months : VPS_TERMS[0].months;
}

/**
 * The public support address, guaranteed non-empty.
 *
 * Shared rather than inlined because it is rendered into `mailto:` hrefs on the public
 * contact page. `saveSettings` happily stores a blank string when an operator clears the
 * field, and `mailto:` with no recipient opens an empty compose window — a visitor who
 * clicks "Email our team" would be left with nowhere to send it and no error to explain
 * why. The hardcoded default is the address the marketing site has always published.
 */
export async function supportEmail(): Promise<string> {
  const v = (await getSetting("support_email")).trim();
  return v || SETTINGS_DEFAULTS.support_email;
}
