"use client";

import { useEffect, useState } from "react";
import { CONSENT_EVENT, getCookieConsent } from "@/lib/consent";
import type { PublicTrackingConfig } from "@/lib/tracking";
import { ConversionTags } from "./ConversionTags";

/**
 * Consent gate for the ad-tracking pixels. Meta Pixel + Google Ads/GA4 are
 * marketing/advertising cookies, so they must not load until the visitor has clicked
 * "Accept all" in the cookie banner (`CookieConsent.tsx`, cookie value "all").
 *
 * SSR renders nothing (consent is unknown on the server); once mounted we read the
 * choice and re-measure on the `CONSENT_EVENT` the banner dispatches, so the tags
 * come to life the instant a visitor accepts — no page reload required. If the
 * operator has set no ids, `ConversionTags` itself still renders nothing, so this
 * stays doubly inert until BOTH an id exists AND consent is granted.
 */
export function ConsentedTags({ config }: { config: PublicTrackingConfig }) {
  const [consented, setConsented] = useState(false);

  useEffect(() => {
    const sync = () => setConsented(getCookieConsent() === "all");
    sync();
    window.addEventListener(CONSENT_EVENT, sync);
    return () => window.removeEventListener(CONSENT_EVENT, sync);
  }, []);

  if (!consented) return null;
  return <ConversionTags config={config} />;
}

