"use client";

import { useEffect } from "react";

/**
 * Fires the browser-side Purchase conversion when a paid order lands here.
 *
 * `lib/fulfil-checkout.ts` tags the post-checkout redirect with the real charged
 * amount when (and only when) IT performed the fulfilment — `?purchase=1&pv=<value>
 * &pc=<currency>&pe=<eventId>`. That same call already fired the server-side Meta
 * Conversions API event with the SAME `eventId`, so when the pixel fires here Meta
 * dedupes the two into ONE conversion.
 *
 * We strip the markers from the URL immediately (history.replaceState) so a refresh
 * or back-navigation can never double-count, then hand the value to `window.nxTrack`
 * (installed by ConversionTags). `nxTrack` only exists once the pixel has loaded,
 * which only happens after cookie consent — so with no ids or no consent this is a
 * silent no-op, and the CAPI event already covered the conversion server-side.
 */
export function PurchaseTracker() {
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get("purchase") !== "1") return;

    const value = Number(params.get("pv") ?? "0");
    const currency = params.get("pc") ?? "USD";
    const eventId = params.get("pe") ?? undefined;

    // Strip the markers before doing anything else so a reload/back cannot re-fire.
    for (const k of ["purchase", "pv", "pc", "pe"]) params.delete(k);
    const qs = params.toString();
    window.history.replaceState(
      null,
      "",
      window.location.pathname + (qs ? `?${qs}` : "") + window.location.hash,
    );

    if (!(value > 0)) return;

    // The pixel loads afterInteractive and only once consent is granted — retry a
    // few seconds for nxTrack to appear, then give up (CAPI already covered it).
    let tries = 0;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const fire = () => {
      const nx = (window as unknown as { nxTrack?: (e: string, p: unknown) => void }).nxTrack;
      if (typeof nx === "function") {
        nx("Purchase", { value, currency, eventId });
        return;
      }
      if (tries++ < 40) timer = setTimeout(fire, 250);
    };
    fire();
    return () => {
      if (timer) clearTimeout(timer);
    };
  }, []);

  return null;
}

